334		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
335		id := mustBuy(t, e, "A", 10, 10)
336	
337		tr := Trade{TradeID: 77, OrderID: id, Symbol: "A", Side: Buy, Price: 9, Qty: 4}
338		res1, err := e.Fill(tr)
339		if err != nil {
340			t.Fatal(err)
341		}
342		recordsBefore := len(e.Records())
343	
344		// 相同编号相同内容：返回原结果，不新增事件，不再次记账。
345		res2, err := e.Fill(tr)
346		if err != nil {
347			t.Fatal(err)
348		}
349		if res1 != res2 {
350			t.Fatalf("幂等结果不一致: %+v vs %+v", res1, res2)
351		}
352		if len(e.Records()) != recordsBefore {
353			t.Fatal("幂等成交不得新增事件记录")
354		}
355		if e.Cash() != 1000-36 || e.Position("A") != 4 || e.ReservedCash() != 60 {
356			t.Fatalf("幂等重放不得再次记账: cash=%d pos=%d reserved=%d", e.Cash(), e.Position("A"), e.ReservedCash())
357		}
358	
359		// 撤销订单后，旧编号重放仍返回原结果，不能再次记账。
360		if err := e.Cancel(id); err != nil {
361			t.Fatal(err)
362		}
363		res3, err := e.Fill(tr)
364		if err != nil {
365			t.Fatal(err)
366		}
367		if res3 != res1 {
368			t.Fatalf("撤单后幂等结果应保持: %+v vs %+v", res3, res1)
369		}
370		if e.Cash() != 1000-36 || e.Position("A") != 4 {
371			t.Fatalf("撤单后重放旧成交不得记账: cash=%d pos=%d", e.Cash(), e.Position("A"))
372		}
373	
374		// 同一编号不同内容：报错且不改状态。记录条数会增加一条拒绝。
375		before := len(e.Records())
376		if _, err := e.Fill(Trade{TradeID: 77, OrderID: id, Symbol: "A", Side: Buy, Price: 8, Qty: 4}); err == nil {
377			t.Fatal("同一编号不同内容必须报错")
378		}
379		if len(e.Records()) != before+1 {
380			t.Fatal("编号冲突拒绝应记录一条拒绝")
381		}
382	
383		// 被拒绝的成交不占用编号：新订单修正后仍可用新编号提交。
384		mustQuote(t, e, "B", Quote{Seq: 1, Moment: 1, Price: 5}, 1)
385		mustSetMax(t, e, "B", 100)
386		b2 := mustBuy(t, e, "B", 10, 5)
387		// 先用编号 88 提交一笔会被拒绝的成交（超量）。
388		if _, err := e.Fill(Trade{TradeID: 88, OrderID: b2, Symbol: "B", Side: Buy, Price: 5, Qty: 99}); err == nil {
389			t.Fatal("超量成交应拒绝")
390		}
391		// 编号 88 未被占用，修正数量后提交成功。
392		if _, err := e.Fill(Trade{TradeID: 88, OrderID: b2, Symbol: "B", Side: Buy, Price: 5, Qty: 2}); err != nil {
393			t.Fatalf("被拒绝编号应可复用: %v", err)
394		}
395	}
