func (k RiskTriggerKind) String() string {
	switch k {
	case RiskTriggerDay:
		return "开日"
	case RiskTriggerLimit:
		return "调限额"
	case RiskTriggerQuote:
		return "报价"
	case RiskTriggerFill:
		return "成交"
	default:
		return "未知"
	}
}

