	if _, err := e.Fill(Trade{TradeID: 1, OrderID: id, Symbol: "A", Side: Buy, Price: 10, Qty: 100}); err != nil {
		t.Fatal(err)
	}
	mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 9}, 1) // 触线
	_, err := e.Buy("A", 1, 10)
	if err == nil {
		t.Fatal("触线后买单必须拒绝")
	}
	if !strings.Contains(err.Error(), "日内亏损已触线") {
		t.Fatalf("拒绝原因应说明触线: %v", err)
	}
}

