	last := recs[len(recs)-1]
	if last.Kind != RecordRejected || last.RiskLoss != 100 || last.RiskLimit != 100 || last.RiskDay != 1 {
		t.Fatalf("拒绝记录应带当日亏损与上限: %+v", last)
	}
	// 撤销记录带亏损与上限。
	cancelRec := recs[len(recs)-2]
	if cancelRec.Kind != RecordCanceled || cancelRec.RiskLoss != 100 || cancelRec.RiskLimit != 100 {
		t.Fatalf("撤销记录应带当日亏损与上限: %+v", cancelRec)
	}

	rec := lastRiskRec(t, e)
	if rec.RiskTrigger != RiskTriggerQuote || rec.RiskQuoteSeq != 2 {
		t.Fatalf("触线记录应注明报价引发及序号: %+v", rec)
	}
	if rec.RiskNetValue != 900 || rec.RiskLoss != 100 || rec.RiskLimit != 100 {
		t.Fatalf("触线记录净值快照错误: %+v", rec)
	}
	if len(rec.Valuations) != 1 || rec.Valuations[0].Symbol != "A" || rec.Valuations[0].Qty != 100 ||
