func TestQuoteTriggerRestrictsAndCancelsBuys(t *testing.T) {
	e, _ := NewEngine(1000)
	mustSetMax(t, e, "A", 100)
	mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
	if err := e.StartDay(1, 100); err != nil {
		t.Fatal(err)
	}
	// 两笔买单：b1 先接受（部分成交），b2 后接受。
	b1 := mustBuy(t, e, "A", 6, 10)
	b2 := mustBuy(t, e, "A", 4, 10)
	if _, err := e.Fill(Trade{TradeID: 1, OrderID: b1, Symbol: "A", Side: Buy, Price: 10, Qty: 6}); err != nil {
		t.Fatal(err)
	}
	// 持仓 6，现金 940，买单剩余占用 40。
	// 报价跌到 5：净值 = 940 + 6×5 = 970，亏损 30，不触线。
	mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 5}, 1)
	if rs := e.RiskStatus(); rs.Restricted {
		t.Fatalf("亏损 30 < 上限 100，不应触线: %+v", rs)
	}
	// 报价跌到 1：净值 = 940 + 6 = 946，亏损 54，仍不触线。
	mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: 1}, 1)
	if rs := e.RiskStatus(); rs.Restricted {
		t.Fatalf("亏损 54 < 上限 100，不应触线: %+v", rs)
	}
	// 报价跌到... 需要亏损 ≥ 100：940 + 6P ≤ 900 → P ≤ -6.6，不可能。
	// 改用更大持仓：再买 4 股（b2 成交），持仓 10，现金 900。
	if _, err := e.Fill(Trade{TradeID: 2, OrderID: b2, Symbol: "A", Side: Buy, Price: 10, Qty: 4}); err != nil {
		t.Fatal(err)
	}
	// 当前报价 1：净值 = 900 + 10 = 910，亏损 90，不触线。
	if rs := e.RiskStatus(); rs.Restricted {
		t.Fatalf("亏损 90 < 上限 100，不应触线: %+v", rs)
	}
	// 报价跌到... 900 + 10P ≤ 900 → P ≤ 0，不可能。需要上限更小。
	// 直接用调上限验证触线。
	if err := e.SetLimit(90); err != nil {
		t.Fatal(err)
	}
	if rs := e.RiskStatus(); !rs.Restricted || rs.Loss != 90 || rs.Limit != 90 {
		t.Fatalf("下调上限到 90 应触线: %+v", rs)
	}
	// 剩余买单全部撤销（b1、b2 均已成交，无剩余；再挂一笔验证撤销）。
	b3 := mustBuy(t, e, "A", 1, 10)
	_ = b3
	// 注意：已触线，新买单应被拒绝。
	if _, err := e.Buy("A", 1, 10); err == nil {
		t.Fatal("触线后新买单必须拒绝")
	}
	_ = b1
}

