content.content:
1	// 日内亏损保护：调用方以递增日号开启交易日，以现金余额加各合约持仓按
2	// 最新已生效报价计算的市值作为基准净值；日内亏损达到或超过上限时立即
3	// 限制增险（拒绝新买单、按订单编号从大到小撤销全部有效买单的未成交部分），
4	// 限制持续到下一交易日。
5	package book
6	
7	import (
8		"fmt"
9		"math"
10		"sort"
11	)
12	
13	// RiskTriggerKind 描述日内亏损触线的引发方式。
14	type RiskTriggerKind int
15	
16	const (
17		// RiskTriggerDay 开日即触线（例如零上限）。
18		RiskTriggerDay RiskTriggerKind = iota + 1
19		// RiskTriggerLimit 调整上限触线。
20		RiskTriggerLimit
21		// RiskTriggerQuote 报价生效触线。
22		RiskTriggerQuote
23		// RiskTriggerFill 成交入账触线。
24		RiskTriggerFill
25	)
26	
27	// String 返回触线原因的中文描述。
28	func (k RiskTriggerKind) String() string {
29		switch k {
30		case RiskTriggerDay:
31			return "开日"
32		case RiskTriggerLimit:
33			return "调限额"
34		case RiskTriggerQuote:
35			return "报价"
36		case RiskTriggerFill:
37			return "成交"
38		default:
39			return "未知"
40		}
41	}
42	
43	// PositionValuation 是触线时刻某个持仓合约的估值快照。
44	type PositionValuation struct {
45		Symbol      string // 合约代码
46		Qty         int64  // 持仓数量
47		QuoteValid  bool   // 是否有有效报价
48		QuoteSeq    int64  // 报价序号
49		QuoteMoment int64  // 报价时刻
50		QuotePrice  int64  // 报价价格
51	}
52	
53	// RiskStatus 是日内风险状态的查询结果。尚未开始交易日时 Started 为 false。
54	type RiskStatus struct {
55		Day        int64 // 当日日号
56		Started    bool  // 是否已开始交易日
57		Baseline   int64 // 基准净值（开日时）
58		NetValue   int64 // 当前净值
59		Loss       int64 // 日内亏损（盈利时为 0）
60		Limit      int64 // 亏损上限
61		Restricted bool  // 是否已触线限制增险
62	}
63	
64	// riskState 是单个交易日的风险状态。
65	type riskState struct {
66		day        int64
67		limit      int64
68		baseline   int64
69		restricted bool
70	}
71	
72	// StartDay 以递增的正整数日号和非负亏损上限开始交易日。
73	// 以现金余额加各合约持仓按最新已生效报价计算的市值作为当日基准净值，
74	// 订单占用资金不重复扣除；零上限在开日时立即触线。
75	//
76	// 日号必须为正整数且不小于已开始的最大日号：
77	//   - 同日号且上限相同：不产生任何变化；
78	//   - 同日号但上限不同：报错且不改状态；
79	//   - 更大日号：重新确定基准净值并清除上一日的限制，但不恢复上一日已撤销的订单；
80	//   - 倒退日号、非正日号或负上限：报错且不改状态。
81	//
82	// 日号不由行情时刻推导，跨日只由调用方明确发起。
83	func (e *Engine) StartDay(day int64, limit int64) error {
84		if day <= 0 {
85			return fmt.Errorf("日号必须为正整数: %d", day)
86		}
87		if limit < 0 {
88			return fmt.Errorf("亏损上限不能为负: %d", limit)
89		}
90		e.mu.Lock()
91		defer e.mu.Unlock()
92	
93		if e.risk != nil {
94			switch {
95			case day == e.risk.day:
96				if limit == e.risk.limit {
97					return nil // 同日号同上限：不产生变化
98				}
99				return fmt.Errorf("日号 %d 已开始，亏损上限为 %d，不能改为 %d", day, e.risk.limit, limit)
100			case day < e.risk.day:
101				return fmt.Errorf("日号不能倒退: 当前日号 %d，请求日号 %d", e.risk.day, day)
102			}
103		}
104	
105		baseline, ok := e.valuationLocked()
106		if !ok {
107			return fmt.Errorf("开日净值超出整数范围，日号 %d 未生效", day)
108		}
109	
110		if e.risk == nil {
111			e.risk = &riskState{}
112		}
113		e.risk.day = day
114		e.risk.limit = limit
115		e.risk.baseline = baseline
116		e.risk.restricted = false
117	
118		if limit == 0 {
119			e.triggerRiskLocked(RiskTriggerDay, 0, 0)
120		}
121		return nil
122	}
123	
124	// SetLimit 在当日调整亏损上限。尚未开始交易日时调用报错。
125	// 上限调高不解除已有的触线限制；上限下调立即按当前净值检查亏损，
126	// 需要时触发与行情触线相同的处理。调整导致净值超出整数范围时整体报错、
127	// 上限不改变。
128	func (e *Engine) SetLimit(limit int64) error {
129		if limit < 0 {
130			return fmt.Errorf("亏损上限不能为负: %d", limit)
131		}
132		e.mu.Lock()
133		defer e.mu.Unlock()
134		if e.risk == nil {
135			return fmt.Errorf("尚未开始交易日，不能调整亏损上限")
136		}
137		if limit == e.risk.limit {
138			return nil
139		}
140		net, ok := e.valuationLocked()
141		if !ok {
142			return fmt.Errorf("净值超出整数范围，亏损上限未调整")
143		}
144		loss := lossLocked(e.risk.baseline, net)
145		lower := limit < e.risk.limit
146		e.risk.limit = limit
147		if lower && loss >= limit && !e.risk.restricted {
148			e.triggerRiskLocked(RiskTriggerLimit, 0, 0)
149		}
150		return nil
151	}
152	
153	// RiskStatus 返回当前风险状态。尚未开始交易日时 Started 为 false，
154	// 其余字段为零值。
155	func (e *Engine) RiskStatus() RiskStatus {
156		e.mu.Lock()
157		defer e.mu.Unlock()
158		if e.risk == nil {
159			return RiskStatus{Started: false}
160		}
161		net, ok := e.valuationLocked()
162		if !ok {
163			// 报价与成交路径已保证估值不溢出，此处为兜底。
164			return RiskStatus{
165				Day:        e.risk.day,
166				Started:    true,
167				Limit:      e.risk.limit,
168				Restricted: e.risk.restricted,
169			}
170		}
171		return RiskStatus{
172			Day:        e.risk.day,
173			Started:    true,
174			Baseline:   e.risk.baseline,
175			NetValue:   net,
176			Loss:       lossLocked(e.risk.baseline, net),
177			Limit:      e.risk.limit,
178			Restricted: e.risk.restricted,
179		}
180	}
