185		total := e.cash
186		for _, st := range e.symbols {
187			if st.position == 0 {
188				continue
189			}
190			price := int64(0)
191			if st.hasQuote {
192				price = st.latest.Price
193			}
194			mv, ok := mulPositive(st.position, price)
