206	// valuationsLocked 返回触线时刻各持仓合约的估值快照（按合约代码排序）。
207	func (e *Engine) valuationsLocked() []PositionValuation {
208		out := make([]PositionValuation, 0)
209		for sym, st := range e.symbols {
210			if st.position == 0 {
211				continue
212			}
213			v := PositionValuation{Symbol: sym, Qty: st.position}
214			if st.hasQuote {
215				v.QuoteValid = true
216				v.QuoteSeq = st.latest.Seq
217				v.QuoteMoment = st.latest.Moment
218				v.QuotePrice = st.latest.Price
219			}
220			out = append(out, v)
221		}
222		sort.Slice(out, func(i, j int) bool { return out[i].Symbol < out[j].Symbol })
223		return out
224	}
