226	// valuationAfterLocked 试算成交入账后的净值。cashBefore 为入账前现金余额，
227	// amount 为成交金额（正数）；返回 false 表示结果超出 int64 范围。
228	func (e *Engine) valuationAfterLocked(cashBefore int64, st *symbolState, o *Order, qty, amount int64) (int64, bool) {
229		cashAfter := cashBefore
230		if o.Side == Buy {
231			cashAfter -= amount
232		} else {
233			if amount > math.MaxInt64-cashBefore {
234				return 0, false
235			}
236			cashAfter += amount
237		}
238		posAfter := st.position
239		if o.Side == Buy {
240			posAfter += qty
241		} else {
242			posAfter -= qty
243		}
244	
245		total := cashAfter
246		for sym, symSt := range e.symbols {
