	}
	mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 9}, 1) // 触线
	rec := lastRiskRec(t, e)
	if rec.RiskNetValue != 900 || rec.RiskLoss != 100 || rec.RiskQuoteSeq != 2 {
		t.Fatalf("触线记录快照错误: %+v", rec)
	}
	// 后续行情、跨日、调限额不改写记录。
	mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: 1}, 1)
	if err := e.StartDay(2, 100); err != nil {
		t.Fatal(err)
	}
	if err := e.SetLimit(1); err != nil {
		t.Fatal(err)
	}
	rec2 := lastRiskRec(t, e)
	// 注意：跨日后 lastRiskRec 会找到新日的触线记录（若有）。这里验证旧记录未被改写。
	recs := e.Records()
	var old Record
	for i := len(recs) - 1; i >= 0; i-- {
		if recs[i].RiskQuoteSeq == 2 && recs[i].RiskDay == 1 {
			old = recs[i]
			break
		}
	}
	if old.RiskNetValue != 900 || old.RiskLoss != 100 || old.RiskQuoteSeq != 2 {
		t.Fatalf("历史触线记录被改写: %+v", old)
	}
	_ = rec
	_ = rec2
}

